#!/usr/bin/env python3
"""Summarize whole native outcomes, near-endpoint tails and true resource bounds."""
import math
from pathlib import Path
from retained_prefix_workflow import D,read,write,sha,route_body
from endpoint_timing_policy import compare
from run_native_scope_policy_v4 import run_dir
b=D/'critical_owner_exchange_dev_01';c=read(b/'completion.json');assert c['passed'];reg=read(b/'registration.json');rows=[];bound={str(p):sha(p) for p in [Path(__file__).resolve(),b/'completion.json',b/'registration.json']}
for name,role in reg['roles'].items():
 r=c['roles'][name];assert r['status']=='legal_evaluated';before=read(Path(role['state'])/'endpoint_vector.json');after=read(Path(r['evaluation'])/'endpoint_vector.json');comparison=compare(before,after);decision=read(b/(name+'_decisions.json'));assert comparison['compatible'];finite={k:v for k,v in after['setup'].items() if isinstance(v,(float,int)) and math.isfinite(v)};worst=min(finite.values());regressions=[x for x in comparison['changes'] if x['kind']=='setup' and x['delta_s']<0];near={}
 for ns in [.01,.05,.1,.2]:
  oldworst=min(v for v in before['setup'].values() if isinstance(v,(int,float)) and math.isfinite(v));oldset={k for k,v in before['setup'].items() if isinstance(v,(int,float)) and math.isfinite(v) and v-oldworst<=ns*1e-9};newset={k for k,v in finite.items() if v-worst<=ns*1e-9};near[str(ns)]=dict(before=len(oldset),after=len(newset),entered=len(newset-oldset),left=len(oldset-newset),regressions_in_current_near=sum(x['endpoint_domain'] in newset for x in regressions))
 root=role['original_budget'];source_physical=read(Path(role['source'])/'independent_audit.json')['physical_metrics'];cur=dict(wirelength=source_physical['planar_wirelength_excluding_sb_half_nodes'],SB_pairs=source_physical['sb_pairs_used'],CB_sources=source_physical['cb_crossing_output_sources_used'])
 rows.append(dict(role=name,status=r['status'],fixed_target=role['fixed_target_paths'],order=role['order'],objective=role['objective'],repair_connections=sum(map(len,role['removed_pins'].values())),CPD_before_ns=before['cpd_s']*1e9,CPD_ns=after['cpd_s']*1e9,CPD_delta_ps=(after['cpd_s']-before['cpd_s'])*1e12,resources=r['resources'],resource_delta={k:r['resources'][k]-cur[k] for k in cur},resource_delta_from_pristine_root={k:r['resources'][k]-root[k] for k in cur},setup_improved=comparison['setup_improved'],setup_regressed=comparison['setup_regressed'],hold_violation_regressions=comparison['hold_violation_regressions'],worst_setup_regression_ps=max([-x['delta_s']*1e12 for x in regressions],default=0.),closest_regressed_margin_ns=min([(x['after_s']-worst)*1e9 for x in regressions],default=None),near_endpoint_sets=near,regressions=regressions,accepted={k:v['accepted'] for k,v in decision.items()},reused_FULLSTA=r['reused_FULL_STA'],evaluation=r['evaluation'],native_core_seconds=r['native_core_seconds'],complete_single_configuration_algorithm_seconds=None))
 for path in [b/(name+'_decisions.json'),Path(r['evaluation'])/'completion.json',Path(r['evaluation'])/'endpoint_vector.json',b/(name+'_audit/analysis.json')]:bound[str(path)]=sha(path)
fixed=c['roles']['000_expanded_preset_weighted'];free=c['roles']['000_expanded_free_weighted'];assert route_body(run_dir(Path(fixed['evaluation']))/'routed.route')==route_body(run_dir(Path(free['evaluation']))/'routed.route')
write(D/'critical_exchange_results_summary_01.json',dict(passed=True,rows=rows,free_and_preset_native_same_candidate=True,interpretation='The existing native weighted kernel reaches the same complete candidate without a preset. Closure extent and order explain the demonstrated tradeoff; no new primitive or benefit of physical+hardcapacity is established. Target-first improves timing while owner-first reduces wire at unchanged CPD/vector.',complete_shared_workflow_seconds=c['complete_orchestrator_seconds'],complete_child_process_seconds=c['complete_child_process_seconds'],complete_single_configuration_algorithm_seconds=None,source_sha256=bound,
 qualification='Five complete legal current-state transactions with matched source/domain/tree scope/order controls as specified. Local precursor model is not a global FPGA bound. Root-relative resource caps are not one common absolute budget across A0/R1/Tf. All endpoint regressions and shared-STA provenance retained; no old U time or borrowed evaluation timing.'))
print([{k:r[k] for k in ['role','CPD_ns','resources','setup_improved','setup_regressed','closest_regressed_margin_ns']} for r in rows])
